/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
let resolveOld;
const initial = { id: 1 };
const feed = createProgressFeed({ initialPacket: initial, decode: packet => packet.id === 2 ? new Promise(resolve => { resolveOld = resolve; }) : packet });
const history = [], shown = [], deltas = [], queue = [];
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record: value => queue.push(value), showQueued() {}, recordProgress: value => history.push(value.frame.id), showProgress: value => shown.push(value.frame.id) });
const stopTelemetry = collectProgressTelemetry(feed, frame => deltas.push(frame.id));
workspace.select({ id: 'a', progressFeed: feed });
assert.deepEqual(shown, [1]);
assert.deepEqual(deltas, []);
feed.emit({ id: 2 });
feed.emit({ id: 3 });
resolveOld({ id: 2 });
await Promise.resolve();
assert.deepEqual(shown, [1, 3]);
assert.deepEqual(history, [1, 3, 2]);
assert.deepEqual(deltas, [1, 3, 2]);
workspace.hide();
workspace.select({ id: 'a', progressFeed: feed });
assert.deepEqual(shown, [1, 3, 1]);
assert.deepEqual(queue.map(x => x.kind), ['select', 'select']);
workspace.dispose();
stopTelemetry();
EOF"

